WFJ.Data.add("book", {
  ["5903870d961c9c4e"] = { "そして族長Var'gazulは、Zul'Gurubの山々の向こうで難を逃れていたが、密林へ出てみると、そこは彼の民が一人残らず洗い流されていた。\n\n彼は絶望した。征服の夢が打ち砕かれたからである。\n\nそしてMin'loth the Serpentが見つかることは、ついになかった。", "." },
  ["591fda09d240e042"] = { "こうなると分かっていたなら、あのルーンの刻まれた木を握らぬよう、自分の手を切り落としていただろう。悔やむことばかりだ！ 後悔とは老人の特権だとずっと思っていた。だが今は分かる。後悔の外套をまとうのは老人ではなく、望みを失った者なのだ。惨めさに丸まった肩から、それを振り払うこともできず、振り払おうともしない者なのだ。\n\nだが、パイプに酔った詩人のような戯言はもうたくさんだ。記録を続けねばならない……", "." },
  ["593c9b224c1a1ad5"] = { "ナイトエルフは気を引き締め、断固たる決意でBurning Legionと戦った。Legionは、長らくWorld Treeの力の源であり、ナイトエルフの王国の心臓そのものでもあるWell of Eternityを求めることを決してやめなかった。計画どおりWorld Treeへの攻撃が成功すれば、悪魔たちは文字どおり世界を引き裂くことになる。", "." },
  ["594d14011437df8d"] = { "Ner'zhulはついに他の世界へのポータルを開いたが、自らが払うことになる恐ろしい代償を予見してはいなかった。ポータルの途方もないエネルギーは、Draenorという世界の構造そのものを引き裂き始めた。Turalyonの軍勢が故郷Azerothへ戻ろうと必死に戦う中、Draenorの世界は内側へと崩れ始めた。Ner'zhulの狂った計画が自らの種族全体を破滅させると悟ったGrom HellscreamとKilrogg Deadeyeは、残るオークたちを結集し、比較的安全なAzerothへと逃れた。", "." },
  ["5973cc032ec16bb4"] = { "DreamerたるYseraもまた、World Treeを自らの領域、すなわちEmerald Dreamとして知られる霊的な次元と結びつけることで、それに魔法をかけた。広大で絶えず移ろう霊の世界であるEmerald Dreamは、物理世界の境界の外に存在していた。Dreamから、Yseraは自然の満ち引きと、世界そのものの進化の道筋を司っていた。", "." },
  ["59b95991d9a48c4e"] = { "竜たちは、世界が再び壮大な大災厄に見舞われぬよう、すばやく動かねばならないと分かっていた。慎重な議論の末、最善の策は、軍勢をその源か、その近くで食い止めることだと決まった。", "." },
  ["59c839c6b0612254"] = { "Tommy Joeへ\n\n時が過ぎるごとに、あなたがいない寂しさで私の心は萎れていきます。ああ、私たちの家族が互いに犯してきた愚かな罪の先を見て、本当の罪はただ一つ、憎しみだけだと分かってくれたなら。憎しみはすべてを蝕みます。この暗くなりゆく時代に、憎しみが私たちの家族だけでなく、もっと多くのものを捕らえてしまうのではないかと恐ろしいのです。\n\nそれに気づいてくれさえすれば、私たちはようやく一緒になれるのに。その日を私は願い、その日のために私は生きています。\n\n愛をこめて\nMaybell", "." },
  ["59ec1685e19c1299"] = { "そして水は密林に降り注ぎ、触れたものすべてを洗い流した。トロールも獣も、水に打ちのめされ溺れながら叫びを上げた。\n\n多くのGurubashiは、なぜ海が自分たちを呑み込むのかと訝ったが、やがて死に、何も知ることはなかった。\n\nそしてついに、水は山々に達したところで止まった。鎮まった水は岸の向こうへと退き、死の爪痕を残していった。\n\n水は退いたが、I'lalaiの周りに押し寄せたままとどまり、都を永遠に沈めたのである。", "." },
})
